import{_ as a,o as e,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"产地 / 处理披露","description":"","frontmatter":{"title":"产地 / 处理披露","grading":"origin-disclosure"},"headers":[],"relativePath":"zh/grading/origin-disclosure.md","filePath":"zh/grading/origin-disclosure.md","lastUpdated":1789241305000}'),d={name:"zh/grading/origin-disclosure.md"};function o(n,t,l,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="产地-处理披露" tabindex="-1">产地 / 处理披露 <a class="header-anchor" href="#产地-处理披露" aria-label="Permalink to &quot;产地 / 处理披露&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>行业规范 (CIBJO / FTC / AGTA) 要求销售方明示宝石是否经过处理以及是否 经过产地判定。常见处理类型依价格影响分级。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>“No Indications of Treatment”表示未观察到处理迹象，不等于绝对证明从未处理；价格也不能仅凭这一项确定。</li><li>一般处理 (常规)：如红/蓝宝石热处理，行业普遍接受，<strong>必须披露</strong>。</li><li>优化处理 (enhancement)：如浸油 (emerald) / 染色 / 填充——价值显著降低。</li><li>产地意见 (origin opinion)：结合包裹体组合与微量元素等证据，由实验室出具意见，不是宝石分级。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>ruby</td><td>heated (H)</td><td>常规 — 价格上限定</td></tr><tr><td>emerald</td><td>minor oil (Cedarwood)</td><td>—</td></tr><tr><td>sapphire</td><td>unheated, Kashmir</td><td>价格差异因品种、产地、质量与市场而异</td></tr></tbody></table><p><em>详见<a href="./intro.html">分级总览</a>。</em></p>',8)])])}const _=a(d,[["render",o]]);export{u as __pageData,_ as default};
